INSERT INTO questions (id, section_id, question_text, answer_choices, correct_answer, explanation, difficulty, is_active) VALUES (1, 1, 'What is the capital of France?', '{"A": "London", "B": "Berlin", "C": "Paris", "D": "Madrid"}'::jsonb, 'C', 'Paris is the capital and largest city of France. It has been the capital since 987 AD.', 'easy', true) ON CONFLICT (id) DO NOTHING;
